class Formatter:
    registry = {}
    def __init_subclass__(cls, *, format_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if format_name is not None:
            if format_name in Formatter.registry:
                raise ValueError("duplicate format")
            Formatter.registry[format_name] = cls

class Upper(Formatter, format_name="upper"):
    def render(self, text):
        return text.upper()

chosen = Formatter.registry["upper"]()
print(chosen.render("hello"))

def two_sum(values, target):
    seen = {}
    for index, value in enumerate(values):
        complement = target - value
        if complement in seen:
            return seen[complement], index
        seen.setdefault(value, index)
    return None

print(two_sum([2, 7, 11, 15], 9))
print(two_sum([3, 3], 6))
print(two_sum([3], 6))

class Key:
    def __init__(self, value):
        self.value = value
    def __hash__(self):
        return 0
    def __eq__(self, other):
        if not isinstance(other, Key):
            return NotImplemented
        return self.value == other.value

mapping = {Key("a"): 1, Key("b"): 2}
print(len(mapping))
print(mapping[Key("a")], mapping[Key("b")])

def require_name(raw):
    name = raw.strip()
    if not name:
        raise ValueError("name is required")
    return name

def register(raw):
    return {"name": require_name(raw)}

def rename(raw):
    return "Renamed to " + require_name(raw)

print(register(" Ada "))
print(rename(" Grace "))

