from typing import Protocol

class Sender(Protocol):
    def send(self, recipient: str, text: str) -> None: ...

class MemorySender:
    def __init__(self):
        self.messages = []
    def send(self, recipient, text):
        self.messages.append((recipient, text))

class Welcome:
    def __init__(self, sender: Sender):
        self.sender = sender
    def run(self, recipient):
        self.sender.send(recipient, "Welcome!")

sender = MemorySender()
Welcome(sender).run("ada@example.test")
print(sender.messages)

def legacy_label(name, active):
    if not name:
        return "unknown"
    return name.strip().upper() + ("!" if active else ".")

cases = [
    ((" Ada ", True), "ADA!"),
    (("Grace", False), "GRACE."),
    (("", True), "unknown"),
    (("   ", False), "."),
]
for args, expected in cases:
    assert legacy_label(*args) == expected
print("4 observed behaviors preserved")

class Customer:
    def __init__(self, discount_percent):
        self.discount_percent = discount_percent
    def discount_for(self, amount):
        return amount * self.discount_percent // 100

def checkout(amount, customer):
    return amount - customer.discount_for(amount)

print(checkout(1000, Customer(15)))

from abc import ABC, abstractmethod

class Pipeline(ABC):
    def run(self, text):
        cleaned = text.strip()
        if not cleaned:
            raise ValueError("empty input")
        return self.transform(cleaned)
    @abstractmethod
    def transform(self, text):
        pass

class Upper(Pipeline):
    def transform(self, text):
        return text.upper()

class Lower(Pipeline):
    def transform(self, text):
        return text.lower()

print(Upper().run(" Ada "))
print(Lower().run(" ADA "))

def parse_count(text):
    try:
        count = int(text)
    except ValueError:
        return "invalid integer"
    else:
        if count < 0:
            return "negative count"
        return count

print(parse_count("12"))
print(parse_count("hello"))
print(parse_count("-1"))

